n class="okv-card"><h2 class="font-display text-xl font-bold text-ink">Lagos zones</h2><div class="mt-4 grid gap-3 sm:grid-cols-2"><?php foreach($zones as $z): ?><form method="post" action="/api/v1/delivery.php" class="flex items-center justify-between gap-3"><?=Csrf::field()?><input type="hidden" name="action" value="set_zone_active"><input type="hidden" name="zone_id" value="<?= (int)$z['id']?>"><span><?=okv_e($z['name'])?></span><label>Active <input type="checkbox" name="is_active" value="1" <?= $z['is_active']?'checked':''?>></label><button class="okv-btn-outline px-3">Save</button></form><?php endforeach;?></div></section></div><?php require __DIR__ . '/../includes/components/admin/footer.php';
